/*
 * Re‑implementation of the original binary‑heap program.
 *
 * Behaviour (as observed from the original, heavily obfuscated binary):
 *
 *   • The program receives its commands as command‑line arguments.
 *   • If no command is supplied (argc < 2) it prints:
 *         NOOP
 *
 *   • Each argument is interpreted as one of the following commands:
 *
 *       I<number>   – insert the signed decimal integer <number> into a
 *                     min‑heap (capacity 15).  On success prints:
 *                         INS <number>
 *                     If the heap is already full prints:
 *                         FULL
 *                     If the number cannot be parsed prints:
 *                         ERR
 *
 *       X           – extract the minimum element from the heap.
 *                     On success prints:
 *                         MIN <value>
 *                     If the heap is empty prints:
 *                         EMPTY
 *
 *   • Any other argument (including malformed “I” commands) results in:
 *         ERR
 *
 * The heap is a classic binary min‑heap stored in a static array of
 * `long` values.  All output is terminated by a newline, exactly as the
 * original program used `puts` / `printf`.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define HEAP_CAPACITY 15

static long heap[HEAP_CAPACITY];
static int  heap_size = 0;

/* --------------------------------------------------------------- */
static void swap(int i, int j)
{
    long tmp = heap[i];
    heap[i] = heap[j];
    heap[j] = tmp;
}

/* --------------------------------------------------------------- */
/* Insert a value into the min‑heap.  Returns 0 on success,
 * 1 if the heap is full.                                           */
static int heap_insert(long value)
{
    if (heap_size >= HEAP_CAPACITY)
        return 1;                     /* full */

    int i = heap_size;
    heap[heap_size++] = value;        /* place at the end */

    /* percolate up */
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap[parent] <= heap[i])
            break;
        swap(parent, i);
        i = parent;
    }
    return 0;
}

/* --------------------------------------------------------------- */
/* Extract the minimum element.  Returns 0 on success,
 * 1 if the heap is empty.  The extracted value is stored in *out.   */
static int heap_extract_min(long *out)
{
    if (heap_size == 0)
        return 1;                     /* empty */

    *out = heap[0];
    heap[0] = heap[--heap_size];      /* move last element to root */

    /* percolate down */
    int i = 0;
    while (1) {
        int left  = 2 * i + 1;
        int right = left + 1;
        int smallest = i;

        if (left < heap_size && heap[left] < heap[smallest])
            smallest = left;
        if (right < heap_size && heap[right] < heap[smallest])
            smallest = right;

        if (smallest == i)
            break;

        swap(i, smallest);
        i = smallest;
    }
    return 0;
}

/* --------------------------------------------------------------- */
int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int idx = 1; idx < argc; ++idx) {
        char *arg = argv[idx];

        if (arg[0] == 'I') {                     /* insert command */
            char *endptr;
            long val = strtol(arg + 1, &endptr, 10);

            if (endptr == arg + 1) {             /* no digits parsed */
                puts("ERR");
                continue;
            }

            if (heap_insert(val)) {
                puts("FULL");
            } else {
                printf("INS %ld\n", val);
            }
        }
        else if (strcmp(arg, "X") == 0) {        /* extract command */
            long min;
            if (heap_extract_min(&min)) {
                puts("EMPTY");
            } else {
                printf("MIN %ld\n", min);
            }
        }
        else {                                   /* unknown command */
            puts("ERR");
        }
    }
    return 0;
}
